{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "@id": "https://kubaik.github.io/7-async-practices-that-cut-meeting-load/#faq",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How do you run an async standup without it becoming ignored?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Use a bot that posts a reminder at a consistent time and aggregates responses. Keep the format short: three questions (done, next, blockers). Have a designated facilitator review updates each morning and follow up on blockers directly. Rotate the facilitator weekly to share the burden. If updates become stale, reduce frequency to three times a week or switch to a weekly written update."
      }
    },
    {
      "@type": "Question",
      "name": "What is the best tool for async decision records?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The best tool is the one your team already uses and will actually check. Common choices include Google Docs (simple, familiar), Notion (structured, searchable), Confluence (integrated with Jira), and plain markdown files in a Git repository (versioned, close to code). Avoid introducing a new tool just for this—the friction of another login will kill adoption. Start with a shared document and a clear template."
      }
    },
    {
      "@type": "Question",
      "name": "How do you handle urgent decisions that can't wait for async?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Define an escalation path. For example: if a decision is needed within 2 hours, use a video call with the minimum necessary people and document the outcome in the decision log afterward. Async is the default, not a religion. The goal is to reduce unnecessary meetings, not to eliminate all real-time collaboration."
      }
    },
    {
      "@type": "Question",
      "name": "Why do async practices fail in some teams?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Async practices fail when they are imposed without addressing underlying issues: lack of trust, unclear ownership, or a culture that rewards presence over output. They also fail when there is no enforcement mechanism—deadlines for comments, facilitators for standups, or clear expectations for response times. Finally, async requires strong writing skills; teams that struggle to communicate in writing may need training or templates before async can work."
      }
    }
  ]
}
